create table customer.customers (id uuid primary key default gen_random_uuid(), auth_user_id uuid unique references auth.users(id) on delete set null, public_id text unique not null default ('CUS-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))), first_name text, last_name text, email text, phone text, status text not null default 'active', metadata jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table customer.addresses (id uuid primary key default gen_random_uuid(), customer_id uuid not null references customer.customers(id) on delete cascade, label text, recipient_name text, phone text, country_code text, governorate text, city text, area text, street text, building text, floor text, apartment text, postal_code text, latitude numeric(10,7), longitude numeric(10,7), is_default boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table catalog.categories (id uuid primary key default gen_random_uuid(), parent_id uuid references catalog.categories(id), slug text unique not null, name_ar text not null, name_en text, description_ar text, description_en text, is_active boolean not null default true, sort_order int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table catalog.products (id uuid primary key default gen_random_uuid(), public_id text unique not null default ('PRD-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))), slug text unique not null, name_ar text not null, name_en text, description_ar text, description_en text, product_type text not null default 'physical', status text not null default 'draft', brand_name text, metadata jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table catalog.product_categories (product_id uuid not null references catalog.products(id) on delete cascade, category_id uuid not null references catalog.categories(id) on delete cascade, primary key(product_id,category_id));
create table catalog.product_variants (id uuid primary key default gen_random_uuid(), product_id uuid not null references catalog.products(id) on delete cascade, sku text unique not null, name_ar text, name_en text, status text not null default 'active', weight_grams numeric(12,3), barcode text unique, attributes jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table catalog.product_media (id uuid primary key default gen_random_uuid(), product_id uuid not null references catalog.products(id) on delete cascade, variant_id uuid references catalog.product_variants(id) on delete cascade, bucket text not null, object_path text not null, media_type text not null default 'image', alt_ar text, alt_en text, sort_order int not null default 0, is_primary boolean not null default false, created_at timestamptz not null default now());
create table catalog.product_stories (id uuid primary key default gen_random_uuid(), product_id uuid not null unique references catalog.products(id) on delete cascade, origin_ar text, origin_en text, story_ar text, story_en text, updated_at timestamptz not null default now());
create table catalog.product_education (id uuid primary key default gen_random_uuid(), product_id uuid not null unique references catalog.products(id) on delete cascade, how_to_use_ar text, how_to_use_en text, ingredients_ar text, ingredients_en text, storage_ar text, storage_en text, warnings_ar text, warnings_en text, updated_at timestamptz not null default now());
create table catalog.prices (id uuid primary key default gen_random_uuid(), product_variant_id uuid not null references catalog.product_variants(id) on delete cascade, currency text not null, amount numeric(18,2) not null check(amount>=0), valid_from timestamptz not null default now(), valid_to timestamptz, channel text not null default 'storefront', priority int not null default 0, is_active boolean not null default true, created_at timestamptz not null default now());
create index idx_prices_variant_currency on catalog.prices(product_variant_id,currency,is_active,valid_from,valid_to);
alter table customer.customers enable row level security;
alter table customer.addresses enable row level security;
alter table catalog.categories enable row level security;
alter table catalog.products enable row level security;
alter table catalog.product_categories enable row level security;
alter table catalog.product_variants enable row level security;
alter table catalog.product_media enable row level security;
alter table catalog.product_stories enable row level security;
alter table catalog.product_education enable row level security;
alter table catalog.prices enable row level security;
create policy customers_self on customer.customers for select to authenticated using(auth_user_id=auth.uid() or platform.has_permission(auth.uid(),'customers.read'));
create policy categories_public_read on catalog.categories for select to anon,authenticated using(is_active);
create policy products_public_read on catalog.products for select to anon,authenticated using(status='active');
create policy variants_public_read on catalog.product_variants for select to anon,authenticated using(status='active');
create policy prices_public_read on catalog.prices for select to anon,authenticated using(is_active and valid_from<=now() and (valid_to is null or valid_to>now()));